# Generated by Manimator. Render with:  manim -pqm scene.py Linear

from manim import *

# Manimator draws text with Crimson Pro, a free font (fonts.google.com). Without it installed,
# Manim uses its default font instead.
Text.set_default(font="Crimson Pro")


class Linear(LinearTransformationScene):
    def __init__(self, **kwargs):
        super().__init__(show_coordinates=True, leave_ghost_vectors=True, **kwargs)

    def construct(self):
        self.add_unit_square()

        # Objects
        square = Square(side_length=2)
        square.set_stroke(BLUE)
        square.set_fill(BLUE)
        square.move_to([1, 1, 0])
        vector = Vector(direction=2 * RIGHT + UP)
        vector.set_color(WHITE)
        dot = Dot(radius=0.1)
        dot.set_stroke(WHITE)
        dot.set_fill(WHITE)
        dot.move_to([1, 0, 0])
        circle = Circle(radius=1)
        circle.set_stroke(RED)
        circle.set_fill(RED)
        circle.move_to([-1, -1, 0])
        text = Text("Hello", font_size=48)
        text.set_color(WHITE)
        text.move_to([0, 3, 0])
        triangle = Triangle()
        triangle.set_stroke(YELLOW)
        triangle.set_fill(YELLOW)
        triangle.move_to([-2, 2, 0])
        arrow = Arrow(start=[-1, -2, 0], end=[1, -2, 0], buff=0)
        arrow.set_color(WHITE)
        star = Star(n=5, outer_radius=1, inner_radius=0.4)
        star.set_stroke(GOLD)
        star.set_fill(GOLD)
        star.move_to([-3, -2, 0])
        rect = Rectangle(width=4, height=2)
        rect.set_stroke(GREEN)
        rect.set_fill(GREEN)
        rect.move_to([3, -2, 0])

        self.add_transformable_mobject(square)
        self.add_vector(vector)
        self.add_transformable_mobject(circle)
        self.add_foreground_mobject(text)
        self.add_vector(arrow)
        self.add(star)
        self.add_foreground_mobject(rect)

        # Animation
        # Scene.play() keeps its own list in self.moving_mobjects, the same attribute
        # LinearTransformationScene reads; empty it so only the grid's objects move.
        self.moving_mobjects = []
        self.apply_matrix([[2, 0], [0, 2]], added_anims=[Indicate(text)], run_time=3)
        self.play(FadeIn(dot), run_time=1)
        self.add_transformable_mobject(dot)
        self.play(FadeOut(circle), run_time=1)
        self.transformable_mobjects.remove(circle)
        self.moving_mobjects = []
        self.apply_inverse([[1, 1], [0, 1]], run_time=3)
        self.moving_mobjects = []
        self.apply_nonlinear_transformation(
            lambda p: np.array([p[0] + np.sin(p[1]), p[1] + np.sin(p[0]), 0]),
            run_time=3,
        )
        self.play(FadeOut(vector), run_time=1)
        self.moving_vectors.remove(vector)
        self.moving_mobjects = []
        self.apply_matrix([[1, 1], [0, 1]], run_time=3)
